unsafe fn hm_destroy(mut hm: *mut hashmap_t) {
    let hm_view: &hashmap_t = unsafe { &*hm };
    let mut i: size_t = 0;
    let mut j: size_t = 0;
    i = 0 as size_t;
    while i < HASHMAP_CELLS as size_t {
        j = 0 as size_t;
        while j < hm_view.cell[i as usize].c {
            free((*hm_view.cell[i as usize].e.offset(j as isize)).k as *mut c_void);
            j = j.wrapping_add(1);
        }
        free(hm_view.cell[i as usize].e as *mut c_void);
        i = i.wrapping_add(1);
    }
}
